import 'package:flutter/material.dart';import 'package:path_provider/path_provider.dart';import 'package:share_plus/share_plus.dart';import '../services/file_service.dart';import '../services/carrier_package.dart';import '../services/vault_store.dart';
class MaskScreen extends StatefulWidget{const MaskScreen({super.key});@override State<MaskScreen> createState()=>_MaskState();}
class _MaskState extends State<MaskScreen>{bool busy=false;String status='Create an explicit image-carrier package (.pvic), or restore files from one.';Future<void> create()async{final carrier=await FileService.pick(extensions:['png','jpg','jpeg','webp']);if(carrier==null)return;final payload=await FileService.pick();if(payload==null)return;setState(()=>busy=true);try{final d=await getTemporaryDirectory();final out=await CarrierPackage.create(carrier,payload,'${d.path}/PixelVault_${DateTime.now().millisecondsSinceEpoch}.pvic');await VaultStore.addFile(out,method:'Carrier package');setState(()=>status='Package created and recorded in the vault.');await Share.shareXFiles([XFile(out.path)],text:'PixelVault carrier package');}catch(e){setState(()=>status='Could not package files: $e');}finally{if(mounted)setState(()=>busy=false);}}
Future<void> extract()async{final f=await FileService.pick(extensions:['pvic']);if(f==null)return;setState(()=>busy=true);try{final d=await getApplicationDocumentsDirectory();final res=await CarrierPackage.extract(f,'${d.path}/restored_${DateTime.now().millisecondsSinceEpoch}');await VaultStore.addFile(res['payload']!,method:'Restored payload');await VaultStore.addFile(res['carrier']!,method:'Restored carrier image');setState(()=>status='Integrity verified. Carrier and payload restored to vault.');}catch(e){setState(()=>status='Restore failed: $e');}finally{if(mounted)setState(()=>busy=false);}}
@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(20),children:[Text('Image carrier',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),Image.asset('assets/images/brand/vault_folder.png',height:170,fit:BoxFit.contain),const SizedBox(height:8),const Text('Package an image and a file together in a documented, integrity-checked .pvic container. This prototype does not conceal payload bytes inside image pixels.'),const SizedBox(height:20),FilledButton.icon(onPressed:busy?null:create,icon:const Icon(Icons.add_photo_alternate),label:const Text('Create carrier package')),const SizedBox(height:12),OutlinedButton.icon(onPressed:busy?null:extract,icon:const Icon(Icons.unarchive),label:const Text('Restore .pvic package')),const SizedBox(height:18),if(busy)const LinearProgressIndicator(),Card(child:Padding(padding:const EdgeInsets.all(16),child:Text(status)))]);}
